# 1. Inherit in Python model
class MyCustomDoc(models.Model):
    _name = 'my.custom.doc'
    _inherit = ['my.custom.doc', 'print.hub.mixin']

    def action_direct_print(self):
        self.ensure_one()
        return self.print_via_hub(
            report_name='my_module.report_custom_template',
            options={
                'copies': 1,
                'branch_code': 'HRMSBY',  # optional branch override
            }
        )

    def action_fast_continuous_form(self):
        # Ultra-fast continuous dot-matrix printing
        return self.print_via_hub_template(
            template_slug='odoo_surat_jalan_continuous',
            data_dict={'doc_no': self.name, 'customer': self.partner_id.name}
        )

    def action_batch_print(self):
        # Spool up to 50 records in a single high-speed batch
        return self.print_batch_via_hub(report_name='my_module.report_invoice')
